perl -e '
use strict;
use warnings;
use File::Find;

my $root = "/bench/repo";
my $internal = "$root/internal";

my @decls;
find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $path = $File::Find::name;
  open my $fh, "<", $path or die $!;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      push @decls, {name=>$2, recv=>$1//"", path=>$path, line=>$i};
    }
  }
}, $internal);

print "declarations: ", scalar(@decls), "\n";
my %names;
$names{$_->{name}}++ for @decls;
print "duplicate names:\n";
for my $n (sort { $names{$b} <=> $names{$a} || $a cmp $b } keys %names) {
  print "  $n: $names{$n}\n" if $names{$n} > 1;
}
print "\nall decls:\n";
for my $d (sort { $a->{name} cmp $b->{name} || $a->{path} cmp $b->{path} } @decls) {
  my $rel = $d->{path}; $rel =~ s{^\Q$root\E/}{};
  printf "  %-40s recv=%-30s %s:%d\n", $d->{name}, ($d->{recv}||"-"), $rel, $d->{line};
}
'

