perl -e '
# Extract exported decls from internal, count call sites across backend .go files
open F, "/tmp/internal_files.txt" or die $!;
my @decls;
my %seen; # name -> [path, recv]
while (my $path = <F>) {
  chomp $path;
  open my $fh, "<", $path or die $!;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Z]\w*)\s*\(/) {
      my ($recv, $name) = ($1||"", $2);
      push @decls, [$name, $recv, $path, $i] unless $seen{"$name|$path|$recv"}++;
    }
  }
}

# collect all go files except proto/gen and vendor
open P, "find /bench/repo -name \"*.go\" ! -path \"*/proto/gen/*\" ! -path \"*/.git/*\" |" or die $!;
my @files;
while (<P>) { chomp; push @files, $_; }

# For each unique exported name, count identifier occurrences that look like calls
# This is approximate: Name( or .Name( or pkg.Name(
my %name_to_decls;
for my $d (@decls) {
  push @{$name_to_decls{$d->[0]}}, $d;
}

my @results;
for my $name (keys %name_to_decls) {
  my $decl_count = scalar @{$name_to_decls{$name}};
  my $pat = qr/\b\Q$name\E\s*\(/;
  my $calls = 0;
  my $files_hit = 0;
  my @sample;
  for my $f (@files) {
    open my $fh, "<", $f or next;
    my $local = 0;
    while (<$fh>) {
      # skip the declaration line itself
      next if /^func\s+/ && /\b\Q$name\E\s*\(/;
      if (/$pat/) {
        $calls++;
        $local++;
        push @sample, "$f:$.:$_" if @sample < 3;
      }
    }
    $files_hit++ if $local;
  }
  # subtract nothing else
  push @results, [$name, $calls, $files_hit, $decl_count, $name_to_decls{$name}[0][2]];
}

@results = sort { $b->[1] <=> $a->[1] || $a->[0] cmp $b->[0] } @results;
print "TOP exported by call-site count (decl lines excluded):\n";
for my $i (0..29) {
  last unless $results[$i];
  my ($n,$c,$fh,$dc,$p) = @{$results[$i]};
  $p =~ s{^/bench/repo/}{};
  printf "%4d calls / %2d files / %d decls  %-35s %s\n", $c, $fh, $dc, $n, $p;
}
'

perl -e '
open F, "/tmp/internal_files.txt" or die $!;
my @decls;
my %namecount;
while (my $path = <F>) {
  chomp $path;
  open my $fh, "<", $path or die $!;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/) {
      my ($recv, $name) = ($1||"", $2);
      next if $name eq "init";
      push @decls, [$name, $recv, $path, $i];
      $namecount{$name}++;
    }
  }
}

# unique names only
my @unique = grep { $namecount{$_->[0]} == 1 } @decls;

open P, "find /bench/repo -name \"*.go\" ! -path \"*/proto/gen/*\" ! -path \"*/.git/*\" |" or die $!;
my @files;
while (<P>) { chomp; push @files, $_; }

# preload file contents
my @contents;
for my $f (@files) {
  open my $fh, "<", $f or next;
  local $/;
  push @contents, [$f, <$fh>];
}

my @results;
for my $d (@unique) {
  my ($name, $recv, $path, $line) = @$d;
  my $pat = qr/\b\Q$name\E\s*\(/;
  my $calls = 0;
  my $files_hit = 0;
  for my $c (@contents) {
    my $n = () = $c->[1] =~ /$pat/g;
    # subtract declaration if in this file
    if ($c->[0] eq $path && $n > 0) { $n--; }
    if ($n > 0) { $calls += $n; $files_hit++; }
  }
  push @results, [$name, $calls, $files_hit, $recv, $path];
}

@results = sort { $b->[1] <=> $a->[1] || $a->[0] cmp $b->[0] } @results;
print "TOP unique-name funcs/methods by call sites (decl excluded):\n";
for my $i (0..40) {
  last unless $results[$i];
  my ($n,$c,$fh,$recv,$p) = @{$results[$i]};
  $p =~ s{^/bench/repo/}{};
  my $r = $recv ? "($recv)" : "func";
  printf "%4d calls / %2d files  %-35s %-28s %s\n", $c, $fh, $n, $r, $p;
}
'
